import {
  Controller,
  Post,
  Get,
  Param,
  Body,
  UseGuards,
  UseInterceptors,
  UploadedFile,
  ParseFilePipe,
  MaxFileSizeValidator,
  Inject,
  Res,
  StreamableFile,
  Request,
  PayloadTooLargeException,
} from '@nestjs/common';
import { Response } from 'express';
import { FileInterceptor } from '@nestjs/platform-express';
import {
  ApiTags,
  ApiOperation,
  ApiConsumes,
  ApiBody,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { IPFS_PROVIDER, IpfsProvider } from './providers';
import { UploadResponseDto, UnpinDto, UnpinResponseDto } from './dto';
import { VaultService } from '../vault/vault.service';
import { MetricsService } from '../metrics/metrics.service';
import { RequestWithUser } from '../common/types';

const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB

@ApiTags('IPFS')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('ipfs')
export class IpfsController {
  constructor(
    @Inject(IPFS_PROVIDER) private readonly ipfsProvider: IpfsProvider,
    private readonly vaultService: VaultService,
    private readonly metricsService: MetricsService
  ) {}

  @Post('upload')
  @ApiOperation({
    summary: 'Upload encrypted file to IPFS with quota tracking',
    description:
      'Pins encrypted file to IPFS, checks storage quota, and records the pin for quota tracking. All in one atomic request.',
  })
  @ApiConsumes('multipart/form-data')
  @ApiBody({
    schema: {
      type: 'object',
      properties: {
        file: {
          type: 'string',
          format: 'binary',
          description: 'Encrypted file blob (max 100MB)',
        },
      },
      required: ['file'],
    },
  })
  @ApiResponse({
    status: 201,
    description: 'File uploaded, pinned, and recorded successfully',
    type: UploadResponseDto,
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 413,
    description: 'Storage quota exceeded',
  })
  @UseInterceptors(
    FileInterceptor('file', {
      limits: { fileSize: MAX_FILE_SIZE },
    })
  )
  async upload(
    @Request() req: RequestWithUser,
    @UploadedFile(
      new ParseFilePipe({
        validators: [new MaxFileSizeValidator({ maxSize: MAX_FILE_SIZE })],
      })
    )
    file: Express.Multer.File
  ): Promise<UploadResponseDto> {
    const hasQuota = await this.vaultService.checkQuota(req.user.id, file.size);
    if (!hasQuota) throw new PayloadTooLargeException('Storage quota exceeded');

    const endPinTimer = this.metricsService.ipfsIpnsDuration.startTimer({
      operation: 'pin',
      source: '',
    });
    let result: { cid: string; size: number };
    try {
      result = await this.ipfsProvider.pinFile(file.buffer);
      endPinTimer({ result: 'success' });
    } catch (err) {
      endPinTimer({ result: 'error' });
      throw err;
    }

    try {
      await this.vaultService.recordPin(req.user.id, result.cid, result.size);
    } catch (err) {
      await this.ipfsProvider.unpinFile(result.cid).catch(() => undefined);
      throw err;
    }
    this.metricsService.fileUploads.inc();
    this.metricsService.fileUploadBytes.inc(result.size);
    return { cid: result.cid, size: result.size, recorded: true };
  }

  @Post('unpin')
  @ApiOperation({
    summary: 'Unpin file from IPFS',
    description: 'Remove a pinned file from IPFS using its CID.',
  })
  @ApiResponse({
    status: 201,
    description: 'File unpinned successfully',
    type: UnpinResponseDto,
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  async unpin(@Body() dto: UnpinDto): Promise<UnpinResponseDto> {
    await this.ipfsProvider.unpinFile(dto.cid);
    this.metricsService.fileUnpins.inc();
    return { success: true };
  }

  @Get(':cid')
  @ApiOperation({
    summary: 'Get file from IPFS',
    description: 'Download an encrypted file from IPFS via the configured gateway.',
  })
  @ApiResponse({
    status: 200,
    description: 'File retrieved successfully',
    content: {
      'application/octet-stream': {
        schema: {
          type: 'string',
          format: 'binary',
        },
      },
    },
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 404,
    description: 'File not found',
  })
  async get(
    @Param('cid') cid: string,
    @Res({ passthrough: true }) res: Response
  ): Promise<StreamableFile> {
    const endCatTimer = this.metricsService.ipfsIpnsDuration.startTimer({
      operation: 'cat',
      source: '',
    });
    let buffer: Buffer;
    try {
      buffer = await this.ipfsProvider.getFile(cid);
      endCatTimer({ result: 'success' });
    } catch (err) {
      endCatTimer({ result: 'error' });
      throw err;
    }

    this.metricsService.fileDownloads.inc();
    res.set({
      'Content-Type': 'application/octet-stream',
      'Content-Length': buffer.length.toString(),
    });
    return new StreamableFile(buffer);
  }
}

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  ManyToOne,
  JoinColumn,
  Index,
  Unique,
} from 'typeorm';
import { User } from '../../auth/entities/user.entity';

@Entity('pinned_cids')
@Unique(['userId', 'cid'])
export class PinnedCid {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Index()
  @Column({ type: 'uuid', name: 'user_id' })
  userId!: string;

  @ManyToOne(() => User, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user!: User;

  /**
   * IPFS CID (Content Identifier) for the pinned content
   * CIDv1 format (base32 encoded)
   */
  @Column({ type: 'varchar', length: 255 })
  cid!: string;

  /**
   * Size of the pinned content in bytes
   * Used for quota tracking (500 MiB limit)
   */
  @Column({ type: 'bigint', name: 'size_bytes' })
  sizeBytes!: string; // TypeORM returns bigint as string

  @CreateDateColumn({ name: 'pinned_at' })
  pinnedAt!: Date;
}

