   1→/**
   2→ * @cipherbox/sdk - CipherBoxClient
   3→ *
   4→ * Stateful client orchestrating folder CRUD, file upload/download,
   5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
   6→ * stateless functions with internal state management (FolderTree, KeyCache).
   7→ *
   8→ * Design principles:
   9→ * - Zero React/Zustand/browser dependencies
  10→ * - All state flows through typed events (SdkEvent)
  11→ * - Operations are wrapped with withOperation() for consistent
  12→ *   start/end/error event emission
  13→ * - Key material is cleared on destroy()
  14→ */
  15→
  16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
  17→import * as sdkCore from '@cipherbox/sdk-core';
  18→import { createAxiosInstance } from '@cipherbox/api-client';
  19→import { clearBytes } from '@cipherbox/crypto';
  20→import type { FolderChild } from '@cipherbox/core';
  21→import type { CipherBoxClientConfig, FolderState } from './types';
  22→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
  23→import { FolderTree } from './state/folder-tree';
  24→import { KeyCache } from './state/key-cache';
  25→import * as binOps from './bin';
  26→import type { BinState } from './bin';
  27→import * as shareOps from './share';
  28→import type { SentShareInfo } from './share';
  29→
  30→/** Thrown when a bin operation is attempted before loadBin() has been called. */
  31→export class BinNotLoadedError extends Error {
  32→  constructor() {
  33→    super('Bin not loaded');
  34→    this.name = 'BinNotLoadedError';
  35→  }
  36→}
  37→
  38→export class CipherBoxClient {
  39→  private config: CipherBoxClientConfig;
  40→  private ctx: SdkContext;
  41→  private emitter: SdkEventEmitter;
  42→  private folderTree: FolderTree;
  43→  private keyCache: KeyCache;
  44→  private binState: BinState | null = null;
  45→  /** Internal copies of key material — zeroed on destroy() without affecting caller buffers */
  46→  private internalVaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
  47→  private internalRootFolderKey: Uint8Array;
  48→
  49→  constructor(config: CipherBoxClientConfig) {
  50→    // Defensive copy of key material so destroy() only zeroes our copies
  51→    this.internalVaultKeypair = {
  52→      publicKey: new Uint8Array(config.vaultKeypair.publicKey),
  53→      privateKey: new Uint8Array(config.vaultKeypair.privateKey),
  54→    };
  55→    this.internalRootFolderKey = new Uint8Array(config.rootFolderKey);
  56→    this.config = {
  57→      ...config,
  58→      vaultKeypair: this.internalVaultKeypair,
  59→      rootFolderKey: this.internalRootFolderKey,
  60→    };
  61→    const axiosInstance =
  62→      config.axiosInstance ??
  63→      createAxiosInstance({
  64→        baseUrl: config.apiUrl,
  65→        getAccessToken: config.getAccessToken,
  66→        defaultHeaders: config.defaultHeaders,
  67→      });
  68→    this.ctx = {
  69→      apiUrl: config.apiUrl,
  70→      getAccessToken: config.getAccessToken,
  71→      axiosInstance,
  72→    };
  73→    this.emitter = new SdkEventEmitter();
  74→    this.folderTree = new FolderTree();
  75→    this.keyCache = new KeyCache();
  76→  }
  77→
  78→  // ---- Event subscription ----
  79→
  80→  /** Subscribe to SDK events. Returns an unsubscribe function. */
  81→  on(handler: SdkEventHandler): () => void {
  82→    return this.emitter.on(handler);
  83→  }
  84→
  85→  /** Unsubscribe a previously registered handler. */
  86→  off(handler: SdkEventHandler): void {
  87→    this.emitter.off(handler);
  88→  }
  89→
  90→  // ---- Lifecycle ----
  91→
  92→  // ---- Share re-wrapping (internal) ----
  93→
  94→  /**
  95→   * Re-wrap keys for share recipients after adding items to a folder.
  96→   *
  97→   * Queries the share callbacks for active shares covering the folder,
  98→   * then wraps each new item's plaintext key for each recipient.
  99→   * Failures are logged but do not propagate (re-wrapping is best-effort).
 100→   */
 101→  private async reWrapNewItems(
 102→    folderIpnsName: string,
 103→    items: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>
 104→  ): Promise<void> {
 105→    const callbacks = this.config.shareCallbacks;
 106→    if (!callbacks) return;
 107→
 108→    const coveringShares = await callbacks.getCoveringShares(folderIpnsName);
 109→    if (coveringShares.length === 0) return;
 110→
 111→    const { failedRecipients } = await shareOps.reWrapForRecipients({
 112→      coveringShares,
 113→      newItems: items,
 114→      addShareKeysFn: callbacks.addShareKeys,
 115→    });
 116→
 117→    if (failedRecipients.length > 0) {
 118→      console.warn(
 119→        `[SDK] Re-wrapping failed for ${failedRecipients.length} recipient(s):`,
 120→        failedRecipients.map((k) => k.slice(0, 10) + '...')
 121→      );
 122→      this.emitter.emit({
 123→        type: 'share:reWrapFailed',
 124→        folderIpnsName,
 125→        failedRecipients,
 126→      } as SdkEvent);
 127→    }
 128→  }
 129→
 130→  /**
 131→   * Destroy the client, clearing all sensitive state.
 132→   * After calling destroy(), the client instance should not be reused.
 133→   */
 134→  destroy(): void {
 135→    this.folderTree.clear();
 136→    this.keyCache.clear();
 137→    this.emitter.removeAll();
 138→    // Zero internal key copies (defense-in-depth; JS GC may retain copies)
 139→    // Only zeroes our copies, not the caller-provided buffers
 140→    this.internalVaultKeypair.privateKey.fill(0);
 141→    this.internalVaultKeypair.publicKey.fill(0);
 142→    this.internalRootFolderKey.fill(0);
 143→    this.binState = null;
 144→  }
 145→
 146→  /**
 147→   * Check if the SDK already has state for a folder.
 148→   *
 149→   * @param ipnsName - Folder's IPNS name
 150→   * @returns true if the folder is registered in the SDK's FolderTree
 151→   */
 152→  hasFolder(ipnsName: string): boolean {
 153→    return this.folderTree.has(ipnsName);
 154→  }
 155→
 156→  /**
 157→   * Get the current sequence number for a folder in the SDK's internal state.
 158→   * Returns undefined if the folder is not registered.
 159→   */
 160→  getFolderSequenceNumber(ipnsName: string): bigint | undefined {
 161→    return this.folderTree.get(ipnsName)?.sequenceNumber;
 162→  }
 163→
 164→  /**
 165→   * Get the IPNS private key for a folder in the SDK's internal state.
 166→   * Returns undefined if the folder is not registered or has no key.
 167→   *
 168→   * Used by ensureFolderRegistered to preserve SDK's correct IPNS key
 169→   * when the store has an empty placeholder (SDK-created folders store
 170→   * keys internally, not in Zustand).
 171→   */
 172→  getFolderIpnsPrivateKey(ipnsName: string): Uint8Array | undefined {
 173→    const key = this.folderTree.get(ipnsName)?.ipnsKeypair?.privateKey;
 174→    // Return a copy so callers can't mutate internal state
 175→    return key && key.length > 0 ? new Uint8Array(key) : undefined;
 176→  }
 177→
 178→  /**
 179→   * Register an externally-loaded folder into the SDK's internal state.
 180→   *
 181→   * Used when folder metadata is loaded outside the SDK (e.g., by a navigation
 182→   * hook) but the SDK needs to know about the folder for mutation operations
 183→   * (create, rename, move, delete, upload).
 184→   *
 185→   * This is a bridge method for gradual SDK adoption -- eventually all folder
 186→   * loading should go through client.loadFolder().
 187→   *
 188→   * @param ipnsName - Folder's IPNS name
 189→   * @param folderKey - Decrypted AES-256 folder key
 190→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
 191→   * @param children - Current folder children
 192→   * @param sequenceNumber - Current IPNS sequence number
 193→   */
 194→  registerFolder(
 195→    ipnsName: string,
 196→    folderKey: Uint8Array,
 197→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array },
 198→    children: FolderChild[],
 199→    sequenceNumber: bigint
 200→  ): void {
 201→    // Defensive copy so destroy() -> folderTree.clear() doesn't zero caller buffers
 202→    this.folderTree.set(ipnsName, {
 203→      ipnsName,
 204→      folderKey: new Uint8Array(folderKey),
 205→      ipnsKeypair: {
 206→        publicKey: new Uint8Array(ipnsKeypair.publicKey),
 207→        privateKey: new Uint8Array(ipnsKeypair.privateKey),
 208→      },
 209→      sequenceNumber,
 210→      children,
 211→      metadata: null,
 212→      lastLoadedAt: Date.now(),
 213→    });
 214→  }
 215→
 216→  // ---- Internal state access (for bin/share modules) ----
 217→
 218→  /** @internal Get the folder tree for bin/share operations */
 219→  getFolderTree(): FolderTree {
 220→    return this.folderTree;
 221→  }
 222→
 223→  /** @internal Get the SDK context */
 224→  getContext(): SdkContext {
 225→    return this.ctx;
 226→  }
 227→
 228→  /** @internal Get the client config */
 229→  getConfig(): CipherBoxClientConfig {
 230→    return this.config;
 231→  }
 232→
 233→  /** @internal Emit an event (used by bin/share modules) */
 234→  emitEvent(event: SdkEvent): void {
 235→    this.emitter.emit(event);
 236→  }
 237→
 238→  // ---- Folder operations ----
 239→
 240→  /**
 241→   * Load a folder's metadata from IPNS.
 242→   *
 243→   * Resolves the folder's IPNS record, decrypts metadata, stores state
 244→   * internally, and emits a 'folder:loaded' event.
 245→   *
 246→   * @param ipnsName - Folder's IPNS name
 247→   * @param folderKey - Decrypted AES-256 folder key
 248→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
 249→   * @returns The loaded folder state, or null if IPNS record not found
 250→   */
 251→  async loadFolder(
 252→    ipnsName: string,
 253→    folderKey: Uint8Array,
 254→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
 255→  ): Promise<FolderState | null> {
 256→    return this.withOperation('loadFolder', async () => {
 257→      const result = await sdkCore.loadFolderMetadata({
 258→        ipnsName,
 259→        folderKey,
 260→        ctx: this.ctx,
 261→      });
 262→
 263→      if (!result) return null;
 264→
 265→      const state: FolderState = {
 266→        ipnsName,
 267→        folderKey,
 268→        ipnsKeypair,
 269→        sequenceNumber: result.sequenceNumber,
 270→        children: result.metadata.children,
 271→        metadata: result.metadata,
 272→        lastLoadedAt: Date.now(),
 273→      };
 274→
 275→      this.folderTree.set(ipnsName, state);
 276→
 277→      this.emitter.emit({
 278→        type: 'folder:loaded',
 279→        folderId: ipnsName,
 280→        ipnsName,
 281→        children: result.metadata.children,
 282→        sequenceNumber: result.sequenceNumber,
 283→      });
 284→
 285→      return state;
 286→    });
 287→  }
 288→
 289→  /**
 290→   * Create a new subfolder inside an existing folder.
 291→   *
 292→   * Generates IPNS keypair and folder key, wraps with user's public key,
 293→   * adds folder entry to parent metadata, publishes parent IPNS record,
 294→   * and publishes empty folder metadata for the new subfolder.
 295→   *
 296→   * @param parentIpnsName - IPNS name of the parent folder
 297→   * @param name - Name for the new subfolder
 298→   * @returns Created folder's UUID, IPNS name, folder key, and IPNS private key
 299→   */
 300→  async createFolder(
 301→    parentIpnsName: string,
 302→    name: string
 303→  ): Promise<{ id: string; ipnsName: string; folderKey: Uint8Array; ipnsPrivateKey: Uint8Array }> {
 304→    return this.withOperation('createFolder', async () => {
 305→      const parent = this.folderTree.get(parentIpnsName);
 306→      if (!parent) throw new Error('Parent folder not loaded');
 307→
 308→      // 1. Check for duplicate name before allocating keys
 309→      if (parent.children.some((child) => child.name === name)) {
 310→        throw new Error('An item with this name already exists');
 311→      }
 312→
 313→      // 2. Create subfolder (generates keys, wraps with user public key)
 314→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 315→        await sdkCore.createSubfolder({
 316→          name,
 317→          userPublicKey: this.config.vaultKeypair.publicKey,
 318→          teeKeys: this.config.teeKeys,
 319→        });
 320→
 321→      try {
 322→        // 3. Add folder entry to parent's children
 323→        const updatedChildren: FolderChild[] = [...parent.children, folder];
 324→
 325→        // 4. Update parent metadata and publish
 326→        const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
 327→          children: updatedChildren,
 328→          folderKey: parent.folderKey,
 329→          ipnsPrivateKey: parent.ipnsKeypair.privateKey,
 330→          ipnsName: parentIpnsName,
 331→          sequenceNumber: parent.sequenceNumber,
 332→          ctx: this.ctx,
 333→          encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
 334→          keyEpoch,
 335→        });
 336→
 337→        // 5. Update parent state
 338→        parent.children = updatedChildren;
 339→        parent.sequenceNumber = newSequenceNumber;
 340→        parent.lastLoadedAt = Date.now();
 341→        this.folderTree.set(parentIpnsName, parent);
 342→
 343→        // 6. Publish empty metadata for the new subfolder
 344→        await sdkCore.updateFolderMetadataAndPublish({
 345→          children: [],
 346→          folderKey,
 347→          ipnsPrivateKey,
 348→          ipnsName: folder.ipnsName,
 349→          sequenceNumber: 0n,
 350→          ctx: this.ctx,
 351→          encryptedIpnsPrivateKey,
 352→          keyEpoch,
 353→        });
 354→
 355→        // 7. Emit parent folder updated event
 356→        this.emitter.emit({
 357→          type: 'folder:updated',
 358→          folderId: parentIpnsName,
 359→          ipnsName: parentIpnsName,
 360→          children: updatedChildren,
 361→          sequenceNumber: newSequenceNumber,
 362→        });
 363→
 364→        // 8. Re-wrap subfolder key for share recipients (non-blocking)
 365→        if (this.config.shareCallbacks) {
 366→          // Copy folderKey for the detached task — caller may wipe the returned buffer
 367→          const folderKeyCopy = new Uint8Array(folderKey);
 368→          this.reWrapNewItems(parentIpnsName, [
 369→            { keyType: 'folder', itemId: folder.id, plaintextKey: folderKeyCopy },
 370→          ])
 371→            .catch((err) => {
 372→              console.warn('[SDK] Post-createFolder re-wrapping failed:', err);
 373→            })
 374→            .finally(() => {
 375→              clearBytes(folderKeyCopy);
 376→            });
 377→        }
 378→
 379→        return { id: folder.id, ipnsName: folder.ipnsName, folderKey, ipnsPrivateKey };
 380→      } catch (err) {
 381→        // Clear plaintext keys on failure — they won't reach the caller
 382→        clearBytes(folderKey);
 383→        clearBytes(ipnsPrivateKey);
 384→        throw err;
 385→      }
 386→    });
 387→  }
 388→
 389→  /**
 390→   * Rename a child entry (folder or file) in a folder.
 391→   *
 392→   * Updates the name in the folder's metadata and publishes the change.
 393→   *
 394→   * @param folderIpnsName - IPNS name of the folder containing the item
 395→   * @param childId - ID of the child to rename
 396→   * @param newName - New name for the child
 397→   */
 398→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
 399→    return this.withOperation('renameItem', async () => {
 400→      const folder = this.folderTree.get(folderIpnsName);
 401→      if (!folder) throw new Error('Folder not loaded');
 402→
 403→      // 1. Rename in metadata (pure operation)
 404→      const { updatedChildren } = sdkCore.renameInFolder({
 405→        children: folder.children,
 406→        childId,
 407→        newName,
 408→      });
 409→
 410→      // 2. Publish updated metadata
 411→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
 412→        children: updatedChildren,
 413→        folderKey: folder.folderKey,
 414→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
 415→        ipnsName: folderIpnsName,
 416→        sequenceNumber: folder.sequenceNumber,
 417→        ctx: this.ctx,
 418→      });
 419→
 420→      // 3. Update internal state
 421→      folder.children = updatedChildren;
 422→      folder.sequenceNumber = newSequenceNumber;
 423→      folder.lastLoadedAt = Date.now();
 424→      this.folderTree.set(folderIpnsName, folder);
 425→
 426→      // 4. Emit update event
 427→      this.emitter.emit({
 428→        type: 'folder:updated',
 429→        folderId: folderIpnsName,
 430→        ipnsName: folderIpnsName,
 431→        children: updatedChildren,
 432→        sequenceNumber: newSequenceNumber,
 433→      });
 434→    });
 435→  }
 436→
 437→  /**
 438→   * Move a child entry between two folders.
 439→   *
 440→   * Removes from source, adds to destination, publishes both IPNS records
 441→   * (destination first for crash safety -- add-before-remove pattern).
 442→   *
 443→   * @param sourceIpnsName - IPNS name of the source folder
 444→   * @param destIpnsName - IPNS name of the destination folder
 445→   * @param childId - ID of the child to move
 446→   */
 447→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
 448→    return this.withOperation('moveItem', async () => {
 449→      const source = this.folderTree.get(sourceIpnsName);
 450→      const dest = this.folderTree.get(destIpnsName);
 451→      if (!source) throw new Error('Source folder not loaded');
 452→      if (!dest) throw new Error('Destination folder not loaded');
 453→
 454→      // 1. Compute updated children for both folders (pure operation)
 455→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
 456→        sourceChildren: source.children,
 457→        destChildren: dest.children,
 458→        childId,
 459→      });
 460→
 461→      // 2. Publish destination first (add-before-remove for crash safety)
 462→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
 463→        children: updatedDestChildren,
 464→        folderKey: dest.folderKey,
 465→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
 466→        ipnsName: destIpnsName,
 467→        sequenceNumber: dest.sequenceNumber,
 468→        ctx: this.ctx,
 469→      });
 470→
 471→      // 3. Publish source (remove)
 472→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
 473→        children: updatedSourceChildren,
 474→        folderKey: source.folderKey,
 475→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
 476→        ipnsName: sourceIpnsName,
 477→        sequenceNumber: source.sequenceNumber,
 478→        ctx: this.ctx,
 479→      });
 480→
 481→      // 4. Update internal state
 482→      source.children = updatedSourceChildren;
 483→      source.sequenceNumber = sourceResult.newSequenceNumber;
 484→      dest.children = updatedDestChildren;
 485→      dest.sequenceNumber = destResult.newSequenceNumber;
 486→      this.folderTree.set(sourceIpnsName, source);
 487→      this.folderTree.set(destIpnsName, dest);
 488→
 489→      // 5. Emit events for both folders
 490→      this.emitter.emit({
 491→        type: 'folder:updated',
 492→        folderId: sourceIpnsName,
 493→        ipnsName: sourceIpnsName,
 494→        children: updatedSourceChildren,
 495→        sequenceNumber: sourceResult.newSequenceNumber,
 496→      });
 497→      this.emitter.emit({
 498→        type: 'folder:updated',
 499→        folderId: destIpnsName,
 500→        ipnsName: destIpnsName,
 501→        children: updatedDestChildren,
 502→        sequenceNumber: destResult.newSequenceNumber,
 503→      });
 504→    });
 505→  }
 506→
 507→  /**
 508→   * Delete a child entry from a folder's metadata.
 509→   *
 510→   * This is a simple metadata delete -- it does NOT move to bin.
 511→   * Use deleteToBin() for soft-delete with bin support.
 512→   *
 513→   * @param folderIpnsName - IPNS name of the folder containing the item
 514→   * @param childId - ID of the child to delete
 515→   * @returns The removed child entry
 516→   */
 517→  async deleteItem(folderIpnsName: string, childId: string): Promise<{ removedItem: FolderChild }> {
 518→    return this.withOperation('deleteItem', async () => {
 519→      const folder = this.folderTree.get(folderIpnsName);
 520→      if (!folder) throw new Error('Folder not loaded');
 521→
 522→      // 1. Remove from metadata (pure operation)
 523→      const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
 524→        children: folder.children,
 525→        childId,
 526→      });
 527→
 528→      // 2. Publish updated metadata
 529→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
 530→        children: updatedChildren,
 531→        folderKey: folder.folderKey,
 532→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
 533→        ipnsName: folderIpnsName,
 534→        sequenceNumber: folder.sequenceNumber,
 535→        ctx: this.ctx,
 536→      });
 537→
 538→      // 3. Update internal state
 539→      folder.children = updatedChildren;
 540→      folder.sequenceNumber = newSequenceNumber;
 541→      folder.lastLoadedAt = Date.now();
 542→      this.folderTree.set(folderIpnsName, folder);
 543→
 544→      // 4. Emit update event
 545→      this.emitter.emit({
 546→        type: 'folder:updated',
 547→        folderId: folderIpnsName,
 548→        ipnsName: folderIpnsName,
 549→        children: updatedChildren,
 550→        sequenceNumber: newSequenceNumber,
 551→      });
 552→
 553→      return { removedItem };
 554→    });
 555→  }
 556→
 557→  // ---- File operations ----
 558→
 559→  /**
 560→   * Upload a file to a folder.
 561→   *
 562→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
 563→   * adds a FilePointer to the parent folder's metadata, and publishes.
 564→   *
 565→   * @param folderIpnsName - IPNS name of the target folder
 566→   * @param data - Raw file content as Uint8Array
 567→   * @param fileName - Display name for the file
 568→   * @param mimeType - MIME type of the file
 569→   * @param onProgress - Optional upload progress callback
 570→   * @returns CID of the uploaded encrypted file
 571→   */
 572→  async uploadFile(
 573→    folderIpnsName: string,
 574→    data: Uint8Array,
 575→    fileName: string,
 576→    mimeType: string,
 577→    onProgress?: ProgressCallback
 578→  ): Promise<{ cid: string }> {
 579→    return this.withOperation('uploadFile', async () => {
 580→      const folder = this.folderTree.get(folderIpnsName);
 581→      if (!folder) throw new Error('Folder not loaded');
 582→
 583→      if (folder.children.some((child) => child.name === fileName)) {
 584→        throw new Error('An item with this name already exists');
 585→      }
 586→
 587→      const fileId = crypto.randomUUID();
 588→
 589→      // 1. Encrypt and upload file, create file metadata
 590→      const uploadResult = await sdkCore.uploadFile({
 591→        data,
 592→        fileId,
 593→        mimeType,
 594→        folderKey: folder.folderKey,
 595→        userPublicKey: this.config.vaultKeypair.publicKey,
 596→        ctx: this.ctx,
 597→        onProgress,
 598→        teeKeys: this.config.teeKeys,
 599→      });
 600→
 601→      try {
 602→        // 2. Add FilePointer to folder's children
 603→        const { updatedChildren } = sdkCore.addFilePointerToFolder({
 604→          children: folder.children,
 605→          fileId,
 606→          fileName,
 607→          fileMetaIpnsName: uploadResult.fileMetaIpnsName,
 608→          ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
 609→        });
 610→
 611→        // 3. Concurrent: file IPNS batch publish + folder metadata update
 612→        //    These two operations are independent -- no data dependency between them.
 613→        //    Using Promise.allSettled to handle partial failures gracefully.
 614→        const [batchResult, folderResult] = await Promise.allSettled([
 615→          sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord], this.ctx),
 616→          sdkCore.updateFolderMetadataAndPublish({
 617→            children: updatedChildren,
 618→            folderKey: folder.folderKey,
 619→            ipnsPrivateKey: folder.ipnsKeypair.privateKey,
 620→            ipnsName: folderIpnsName,
 621→            sequenceNumber: folder.sequenceNumber,
 622→            ctx: this.ctx,
 623→          }),
 624→        ]);
 625→
 626→        // Folder metadata update is critical -- must succeed for upload to be valid
 627→        if (folderResult.status === 'rejected') {
 628→          throw folderResult.reason;
 629→        }
 630→
 631→        // File IPNS batch publish failure is non-critical -- the FilePointer in
 632→        // folder metadata is valid, and the file IPNS record will be created
 633→        // on next publish attempt or TEE republish cycle
 634→        // Note: if folder update fails but batch publish succeeded, an orphaned IPNS
 635→        // record may exist. This is benign -- no FilePointer references it, and the
 636→        // IPNS name will be reused on the next successful upload attempt.
 637→        if (batchResult.status === 'rejected') {
 638→          const batchError =
 639→            batchResult.reason instanceof Error
 640→              ? batchResult.reason
 641→              : new Error(String(batchResult.reason));
 642→          console.warn(
 643→            '[SDK] File IPNS batch publish failed (non-critical, will retry on next publish):',
 644→            batchError
 645→          );
 646→          this.emitter.emit({
 647→            type: 'ipns:batchPublishFailed',
 648→            ipnsNames: [uploadResult.ipnsRecord.ipnsName],
 649→            error: batchError,
 650→          });
 651→        } else if (batchResult.value?.totalFailed > 0) {
 652→          // Server accepted the request but reported partial failure for some records
 653→          console.warn(
 654→            `[SDK] File IPNS batch publish partially failed: ${batchResult.value.totalFailed} of ${batchResult.value.totalFailed + batchResult.value.totalSucceeded} records failed`
 655→          );
 656→          this.emitter.emit({
 657→            type: 'ipns:batchPublishFailed',
 658→            ipnsNames: [uploadResult.ipnsRecord.ipnsName],
 659→            error: new Error(
 660→              `Batch publish partial failure: ${batchResult.value.totalFailed} record(s) failed`
 661→            ),
 662→          });
 663→        }
 664→
 665→        const { newSequenceNumber } = folderResult.value;
 666→
 667→        // 4. Update internal state
 668→        folder.children = updatedChildren;
 669→        folder.sequenceNumber = newSequenceNumber;
 670→        folder.lastLoadedAt = Date.now();
 671→        this.folderTree.set(folderIpnsName, folder);
 672→
 673→        // 5. Emit events
 674→        this.emitter.emit({
 675→          type: 'file:uploaded',
 676→          folderId: folderIpnsName,
 677→          fileName,
 678→          cid: uploadResult.cid,
 679→        });
 680→        this.emitter.emit({
 681→          type: 'folder:updated',
 682→          folderId: folderIpnsName,
 683→          ipnsName: folderIpnsName,
 684→          children: updatedChildren,
 685→          sequenceNumber: newSequenceNumber,
 686→        });
 687→
 688→        // 6. Re-wrap file key for share recipients (best-effort)
 689→        try {
 690→          if (this.config.shareCallbacks) {
 691→            await this.reWrapNewItems(folderIpnsName, [
 692→              { keyType: 'file', itemId: fileId, plaintextKey: uploadResult.fileKey },
 693→            ]);
 694→          }
 695→        } catch (err) {
 696→          console.warn('[SDK] Post-upload re-wrapping failed:', err);
 697→        }
 698→
 699→        return { cid: uploadResult.cid };
 700→      } finally {
 701→        clearBytes(uploadResult.fileKey);
 702→      }
 703→    });
 704→  }
