36→  /** Base URL for the CipherBox API (e.g., "https://api.cipherbox.cc") */
37→  apiUrl: string;
38→  /** Returns a valid access token. Consumer owns refresh logic. */
39→  getAccessToken: () => Promise<string>;
40→  /** User's vault keypair (secp256k1). Used for ECIES operations. */
