 1→/**
 2→ * Key Manager Service
 3→ *
 4→ * ECIES decryption of IPNS private keys with epoch fallback and re-encryption.
 5→ * - Decrypts IPNS keys encrypted with TEE epoch public key
 6→ * - Supports fallback to previous epoch during grace period
 7→ * - Re-encrypts old-epoch keys with current epoch key
 8→ *
 9→ * SECURITY: Caller is responsible for zeroing returned IPNS private keys after use.
10→ */
11→
12→import { decrypt, encrypt } from 'eciesjs';
13→import { getKeypair, getPublicKey } from './tee-keys.js';
14→
15→/**
16→ * Decrypt an ECIES-encrypted IPNS private key using the specified epoch's private key.
17→ *
18→ * @param encryptedIpnsKey - ECIES ciphertext containing the IPNS Ed25519 private key
19→ * @param epoch - The key epoch to use for decryption
20→ * @returns 32-byte Ed25519 IPNS private key
21→ * @throws Error if decryption fails (wrong epoch or corrupted data)
22→ */
23→export async function decryptIpnsKey(
24→  encryptedIpnsKey: Uint8Array,
25→  epoch: number
26→): Promise<Uint8Array> {
27→  const keypair = await getKeypair(epoch);
28→  try {
29→    return new Uint8Array(decrypt(keypair.privateKey, encryptedIpnsKey));
30→  } finally {
31→    keypair.privateKey.fill(0);
32→  }
33→}
34→
35→/**
36→ * Decrypt an IPNS key with fallback from current to previous epoch.
37→ *
38→ * Tries the current epoch first. If decryption fails and a previous epoch
39→ * is provided, tries the previous epoch (grace period support).
40→ *
41→ * @param encryptedIpnsKey - ECIES ciphertext
42→ * @param currentEpoch - Current active epoch number
43→ * @param previousEpoch - Previous epoch number (null if no grace period active)
44→ * @returns Object with decrypted key and which epoch succeeded
45→ * @throws Error if both epochs fail
46→ */
47→export async function decryptWithFallback(
48→  encryptedIpnsKey: Uint8Array,
49→  currentEpoch: number,
50→  previousEpoch: number | null
51→): Promise<{ ipnsPrivateKey: Uint8Array; usedEpoch: number }> {
52→  // Try current epoch first
53→  try {
54→    const ipnsPrivateKey = await decryptIpnsKey(encryptedIpnsKey, currentEpoch);
55→    return { ipnsPrivateKey, usedEpoch: currentEpoch };
56→  } catch {
57→    // Current epoch failed -- try previous if available
58→  }
59→
60→  // Try previous epoch (grace period)
61→  if (previousEpoch !== null) {
62→    try {
63→      const ipnsPrivateKey = await decryptIpnsKey(encryptedIpnsKey, previousEpoch);
64→      return { ipnsPrivateKey, usedEpoch: previousEpoch };
65→    } catch {
66→      // Previous epoch also failed
67→    }
68→  }
69→
70→  throw new Error('ECIES decryption failed for all available epochs');
71→}
72→
73→/**
74→ * Re-encrypt an IPNS private key for a target epoch.
75→ *
76→ * Used during epoch migration: when a key was decrypted with the previous epoch,
77→ * it gets re-encrypted with the current epoch's public key so future republishes
78→ * use the current epoch directly.
79→ *
80→ * @param ipnsPrivateKey - Plaintext 32-byte Ed25519 IPNS private key
81→ * @param targetEpoch - The epoch to encrypt for
82→ * @returns ECIES ciphertext encrypted with target epoch's public key
83→ */
84→export async function reEncryptForEpoch(
85→  ipnsPrivateKey: Uint8Array,
86→  targetEpoch: number
87→): Promise<Uint8Array> {
88→  const targetPublicKey = await getPublicKey(targetEpoch);
89→  const reEncrypted = new Uint8Array(encrypt(targetPublicKey, ipnsPrivateKey));
90→  return reEncrypted;
91→}
92→

  1→/**
  2→ * Republish Route
  3→ *
  4→ * POST /republish - Batch IPNS record signing endpoint.
  5→ *
  6→ * Receives encrypted IPNS private keys, decrypts with epoch-derived keys,
  7→ * signs IPNS records, and returns signed records. Each entry is processed
  8→ * independently -- one failure does not block others.
  9→ *
 10→ * SECURITY:
 11→ * - IPNS private keys are zeroed immediately after signing
 12→ * - No key material appears in logs or error messages
 13→ * - Per-entry error handling with safe error messages
 14→ */
 15→
 16→import { Router, type Request, type Response } from 'express';
 17→import { decryptWithFallback, reEncryptForEpoch } from '../services/key-manager.js';
 18→import { signIpnsRecord } from '../services/ipns-signer.js';
 19→
 20→const router = Router();
 21→
 22→/** Shape of each entry in the republish request */
 23→interface RepublishEntry {
 24→  encryptedIpnsKey: string; // base64-encoded ECIES ciphertext
 25→  keyEpoch: number;
 26→  ipnsName: string;
 27→  latestCid: string;
 28→  sequenceNumber: string; // bigint as string
 29→  currentEpoch: number;
 30→  previousEpoch: number | null;
 31→}
 32→
 33→/** Shape of each result in the republish response */
 34→interface RepublishResult {
 35→  ipnsName: string;
 36→  success: boolean;
 37→  signedRecord?: string; // base64-encoded marshaled IPNS record
 38→  newSequenceNumber?: string;
 39→  upgradedEncryptedKey?: string; // base64, present if re-encrypted for current epoch
 40→  upgradedKeyEpoch?: number;
 41→  error?: string;
 42→}
 43→
 44→router.post('/republish', async (req: Request, res: Response) => {
 45→  const { entries } = req.body as { entries: RepublishEntry[] };
 46→
 47→  if (!entries || !Array.isArray(entries)) {
 48→    res.status(400).json({ error: 'Missing or invalid entries array' });
 49→    return;
 50→  }
 51→
 52→  const results: RepublishResult[] = [];
 53→  let successes = 0;
 54→  let failures = 0;
 55→
 56→  for (const entry of entries) {
 57→    let ipnsPrivateKey: Uint8Array | null = null;
 58→
 59→    try {
 60→      // 1. Decode encrypted IPNS key from base64
 61→      const encryptedIpnsKey = new Uint8Array(Buffer.from(entry.encryptedIpnsKey, 'base64'));
 62→
 63→      // 2. Decrypt with epoch fallback
 64→      const { ipnsPrivateKey: decryptedKey, usedEpoch } = await decryptWithFallback(
 65→        encryptedIpnsKey,
 66→        entry.currentEpoch,
 67→        entry.previousEpoch
 68→      );
 69→      ipnsPrivateKey = decryptedKey;
 70→
 71→      // 3. Sign IPNS record with incremented sequence number
 72→      const newSequenceNumber = BigInt(entry.sequenceNumber) + 1n;
 73→      const signedRecord = await signIpnsRecord(ipnsPrivateKey, entry.latestCid, newSequenceNumber);
 74→
 75→      // 4. Check if re-encryption needed (used previous epoch, not current)
 76→      let upgradedEncryptedKey: string | undefined;
 77→      let upgradedKeyEpoch: number | undefined;
 78→
 79→      if (usedEpoch !== entry.currentEpoch) {
 80→        const reEncrypted = await reEncryptForEpoch(ipnsPrivateKey, entry.currentEpoch);
 81→        upgradedEncryptedKey = Buffer.from(reEncrypted).toString('base64');
 82→        upgradedKeyEpoch = entry.currentEpoch;
 83→      }
 84→
 85→      // 5. IMMEDIATELY zero the IPNS private key
 86→      ipnsPrivateKey.fill(0);
 87→      ipnsPrivateKey = null;
 88→
 89→      // 6. Build success result
 90→      const result: RepublishResult = {
 91→        ipnsName: entry.ipnsName,
 92→        success: true,
 93→        signedRecord: Buffer.from(signedRecord).toString('base64'),
 94→        newSequenceNumber: newSequenceNumber.toString(),
 95→      };
 96→
 97→      if (upgradedEncryptedKey) {
 98→        result.upgradedEncryptedKey = upgradedEncryptedKey;
 99→        result.upgradedKeyEpoch = upgradedKeyEpoch;
100→      }
101→
102→      results.push(result);
103→      successes++;
104→    } catch (error) {
105→      // Ensure key is zeroed even on error
106→      if (ipnsPrivateKey) {
107→        ipnsPrivateKey.fill(0);
108→        ipnsPrivateKey = null;
109→      }
110→
111→      // Never include key material in error messages
112→      results.push({
113→        ipnsName: entry.ipnsName,
114→        success: false,
115→        error: error instanceof Error ? error.message : 'Unknown error',
116→      });
117→      failures++;
118→    }
119→  }
120→
121→  // Log processing summary (NEVER log key material)
122→  console.log(
123→    `Republish batch: ${entries.length} entries, ${successes} successes, ${failures} failures`
124→  );
125→
126→  res.json({ results });
127→});
128→
129→export default router;
130→

 1→import { Module, Logger, OnModuleInit } from '@nestjs/common';
 2→import { BullModule, InjectQueue } from '@nestjs/bullmq';
 3→import { TypeOrmModule } from '@nestjs/typeorm';
 4→import { ConfigModule } from '@nestjs/config';
 5→import { Queue } from 'bullmq';
 6→import { IpnsRepublishSchedule } from './republish-schedule.entity';
 7→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
 8→import { TeeModule } from '../tee/tee.module';
 9→import { DelegatedRoutingModule } from '../ipns/delegated-routing.module';
10→import { RepublishService } from './republish.service';
11→import { RepublishProcessor } from './republish.processor';
12→import { RepublishHealthController } from './republish-health.controller';
13→
14→@Module({
15→  imports: [
16→    BullModule.registerQueue({ name: 'republish' }),
17→    TypeOrmModule.forFeature([IpnsRepublishSchedule, FolderIpns]),
18→    TeeModule,
19→    ConfigModule,
20→    DelegatedRoutingModule,
21→  ],
22→  providers: [RepublishService, RepublishProcessor],
23→  controllers: [RepublishHealthController],
24→  exports: [RepublishService],
25→})
26→export class RepublishModule implements OnModuleInit {
27→  private readonly logger = new Logger(RepublishModule.name);
28→
29→  constructor(@InjectQueue('republish') private readonly queue: Queue) {}
30→
31→  async onModuleInit(): Promise<void> {
32→    try {
33→      // Create repeating job scheduler: every 6 hours
34→      await this.queue.upsertJobScheduler(
35→        'republish-cron',
36→        {
37→          pattern: '0 */6 * * *', // Every 6 hours: 00:00, 06:00, 12:00, 18:00
38→        },
39→        {
40→          name: 'republish-batch',
41→        }
42→      );
43→      this.logger.log('Republish cron scheduler registered: every 6 hours (0 */6 * * *)');
44→    } catch (error) {
45→      // Redis may be unavailable during development
46→      const message = error instanceof Error ? error.message : String(error);
47→      this.logger.warn(`Failed to register republish cron scheduler (non-fatal): ${message}`);
48→    }
49→  }
50→}
