 1→import { Processor, WorkerHost } from '@nestjs/bullmq';
 2→import { Logger } from '@nestjs/common';
 3→import { Job } from 'bullmq';
 4→import { RepublishService } from './republish.service';
 5→import { MetricsService } from '../metrics/metrics.service';
 6→
 7→@Processor('republish')
 8→export class RepublishProcessor extends WorkerHost {
 9→  private readonly logger = new Logger(RepublishProcessor.name);
10→
11→  constructor(
12→    private readonly republishService: RepublishService,
13→    private readonly metricsService: MetricsService
14→  ) {
15→    super();
16→  }
17→
18→  async process(job: Job): Promise<void> {
19→    this.logger.log(`Republish job started: ${job.name} (id: ${job.id})`);
20→    this.metricsService.republishRuns.inc();
21→
22→    const endBatchTimer = this.metricsService.republishBatchDuration.startTimer({
23→      tee_provider: 'mock',
24→    });
25→    let batchResult = 'success';
26→
27→    try {
28→      const result = await this.republishService.processRepublishBatch();
29→
30→      this.metricsService.republishEntriesProcessed.inc({ result: 'succeeded' }, result.succeeded);
31→      this.metricsService.republishEntriesProcessed.inc({ result: 'failed' }, result.failed);
32→
33→      this.logger.log(
34→        `Republish job complete: processed=${result.processed}, succeeded=${result.succeeded}, failed=${result.failed}`
35→      );
36→
37→      // If all entries failed and none succeeded, TEE might be down.
38→      // When TEE recovers, reactivate stale entries.
39→      if (result.processed > 0 && result.succeeded === 0 && result.failed === result.processed) {
40→        batchResult = 'error';
41→        this.logger.warn('All republish entries failed. TEE worker may be unreachable.');
42→      }
43→    } catch (error) {
44→      batchResult = 'error';
45→      const message = error instanceof Error ? error.message : String(error);
46→      this.logger.error(`Republish job failed: ${message}`);
47→      throw error; // Let BullMQ handle retry
48→    } finally {
49→      endBatchTimer({ result: batchResult });
50→    }
51→  }
52→}
