packages/core/src/
  vault/
    types.ts              # Extended with ByoIpfsConfig type in vault metadata

apps/api/src/
  ipfs/
    dto/
      register-cid.dto.ts  # CID registration DTO
    ipfs.controller.ts      # + registerCid endpoint
  vault/
